package com.windowmarkers;

import java.awt.Component;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/** Search activities first, then inspect one source setup and its conditions. */
final class ActivitySetupPicker
{
    static ActivitySetups.Setup choose(Component parent)
    {
        JTextField search=new JTextField(32);
        JComboBox<String> activities=new JComboBox<>();
        JComboBox<ActivitySetups.Setup> setups=new JComboBox<>();
        activities.setMaximumRowCount(12); setups.setMaximumRowCount(12);
        JTextArea notes=new JTextArea(7,48);
        notes.setEditable(false); notes.setLineWrap(true); notes.setWrapStyleWord(true);
        JPanel panel=new MarkerForm();
        panel.add(new JLabel("Search activity")); panel.add(search);
        panel.add(activities); panel.add(new JLabel("Choose a setup")); panel.add(setups);
        panel.add(new JLabel("<html>One Wiki table or example at a time.<br>Review its conditions; quantities and a complete loadout are not assumed.<br>These setups keep all alternatives and start unchecked.</html>"));
        panel.add(notes);
        JButton source=new JButton("Open this Wiki setup source");
        source.addActionListener(e -> {
            ActivitySetups.Setup setup=(ActivitySetups.Setup)setups.getSelectedItem();
            if (setup!=null) { net.runelite.client.util.LinkBrowser.browse(setup.source); }
        });
        panel.add(source);
        setups.addActionListener(e -> {
            ActivitySetups.Setup setup=(ActivitySetups.Setup)setups.getSelectedItem();
            notes.setText(setup==null ? "No matching setup." : setup.notes.isEmpty()
                ? "Check the linked guide for skill, quest and encounter requirements." : setup.notes);
            notes.setCaretPosition(0); source.setEnabled(setup!=null);
        });
        activities.addActionListener(e -> {
            setups.removeAllItems();
            for (ActivitySetups.Setup setup:ActivitySetups.forActivity((String)activities.getSelectedItem()))
            { setups.addItem(setup); }
        });
        Runnable refresh=() -> {
            Object previous=activities.getSelectedItem();
            activities.removeAllItems();
            for (String activity:ActivitySetups.activities(search.getText())) { activities.addItem(activity); }
            if (previous!=null && ActivitySetups.activities(search.getText()).contains(previous))
            { activities.setSelectedItem(previous); }
        };
        search.getDocument().addDocumentListener(new DocumentListener()
        {
            public void insertUpdate(DocumentEvent e) { refresh.run(); }
            public void removeUpdate(DocumentEvent e) { refresh.run(); }
            public void changedUpdate(DocumentEvent e) { refresh.run(); }
        });
        refresh.run();
        if (!MarkerDialogs.confirm(parent,panel,"Choose a Wiki activity setup",680,520)) { return null; }
        return (ActivitySetups.Setup)setups.getSelectedItem();
    }
}

package com.windowmarkers;

import java.util.*;

/** Exact owned-item membership in one explicitly selected Wiki example. */
final class ActivitySetups
{
    static final class Setup
    {
        final String id, activity, label, source, notes;
        final Set<Integer> itemIds=new HashSet<>();
        Setup(String[] row)
        { id=row[0]; activity=row[1]; label=row[2]; source=row[3]; notes=row[4]; }
        @Override public String toString() { return label; }

        Map<String,List<AutoCategories.Item>> suggest(List<AutoCategories.Item> owned)
        {
            Map<String,List<AutoCategories.Item>> result=new LinkedHashMap<>();
            for (AutoCategories.Item item:owned)
            {
                if (!itemIds.contains(item.id)) { continue; }
                String group=ItemVariantState.needsActivityReview(item)
                    ? ItemVariantState.reviewGroup(item) : label+" — setup review";
                AutoCategories.add(result,activity+" — "+ItemVariantState.annotate(group,item),item);
            }
            return result;
        }
    }
    private static final Map<String,Setup> SETUPS=new LinkedHashMap<>();
    static
    {
        for (String[] row:ItemTaxonomy.readRows("activity-setups.tsv",5))
        {
            if (SETUPS.put(row[0],new Setup(row))!=null) { throw new IllegalStateException("Duplicate activity setup"); }
        }
        for (String[] row:ItemTaxonomy.readRows("activity-setup-items.tsv",2))
        {
            Setup setup=SETUPS.get(row[0]);
            if (setup==null) { throw new IllegalStateException("Missing activity setup"); }
            setup.itemIds.add(Integer.parseInt(row[1]));
        }
    }
    static List<String> activities(String search)
    {
        String needle=search.trim().toLowerCase(Locale.ROOT);
        Set<String> result=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
        for (Setup setup:SETUPS.values())
        { if (setup.activity.toLowerCase(Locale.ROOT).contains(needle)) { result.add(setup.activity); } }
        return new ArrayList<>(result);
    }
    static List<Setup> all() { return new ArrayList<>(SETUPS.values()); }
    static List<Setup> forActivity(String activity)
    {
        List<Setup> result=new ArrayList<>();
        for (Setup setup:SETUPS.values()) { if (setup.activity.equals(activity)) { result.add(setup); } }
        return result;
    }
}

package com.windowmarkers;

import java.util.*;

/** Local, reviewable facts. Activity suitability is never inferred from Eat/Drink or stat totals. */
final class AutoCategories
{
    enum Preset
    {
        ALL_CATEGORIES("All classifications"), BROAD_TYPES("Broad item types"),
        SKILLING("Skilling — outfits, tools, boosts and materials"), SKILLING_OUTFITS("Skilling outfits only"),
        COMBAT_GROUPS("General combat and equipment sets"), FOOD_AND_POTIONS("Food, potions and restricted supplies"),
        TRAVEL_AND_UTILITY("Travel, storage and utility"), QUESTS_AND_CLUES("Quest and clue items"), COSMETICS("Cosmetic and utility equipment"),
        RAID_MEGA_RARES("Raid mega-rare weapons"),
        CHAMBERS_OF_XERIC("Chambers of Xeric — Wiki gear and supplies"), THEATRE_OF_BLOOD("Theatre of Blood — Wiki gear and supplies"), TOMBS_OF_AMASCUT("Tombs of Amascut — Wiki gear and supplies"),
        FRACTURED_ARCHIVE("The Fractured Archive — provisional Wiki setups"),
        WIKI_ACTIVITY_SETUP("Choose a Wiki activity and setup…");
        private final String label;
        Preset(String label) { this.label=label; }
        @Override public String toString() { return label; }
    }
    static final class Item
    {
        final int id; final String name; final boolean equipment; final String[] actions;
        final int melee, ranged, magic;
        Item(int id,String name,boolean equipment,String[] actions,int melee,int ranged,int magic)
        { this.id=id; this.name=name.toLowerCase(Locale.ROOT); this.equipment=equipment; this.actions=actions; this.melee=melee; this.ranged=ranged; this.magic=magic; }
        boolean action(String action) { return actions!=null && Arrays.stream(actions).anyMatch(action::equalsIgnoreCase); }
    }
    static Map<String,List<Item>> suggest(Preset preset,List<Item> items)
    {
        Map<String,List<Item>> groups=new LinkedHashMap<>();
        if (preset==Preset.WIKI_ACTIVITY_SETUP) { return groups; }
        if (preset!=Preset.RAID_MEGA_RARES && preset!=Preset.CHAMBERS_OF_XERIC && preset!=Preset.THEATRE_OF_BLOOD && preset!=Preset.TOMBS_OF_AMASCUT && preset!=Preset.FRACTURED_ARCHIVE)
        {
            for (Item item : items)
            {
                if (ItemVariantState.identityNeedsReview(item))
                {
                    if (preset==Preset.BROAD_TYPES || preset==Preset.ALL_CATEGORIES)
                    { add(groups,ItemVariantState.reviewGroup(item),item); }
                    continue;
                }
                boolean standalone=standaloneSetWeapon(item,items);
                String group;
                if (preset==Preset.BROAD_TYPES || preset==Preset.ALL_CATEGORIES) { group=standalone ? ItemTaxonomy.weaponRole(ItemVariantState.familyName(item)) : category(item,true); }
                else if (preset==Preset.COMBAT_GROUPS)
                {
                    group=WikiCatalogue.category(item,preset);
                    String set=ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item)), role=ItemTaxonomy.weaponRole(ItemVariantState.familyName(item));
                    if (set!=null && !standalone) { group=set; }
                    else if (role!=null && !role.equals("Tools")) { group=role; }
                    else if ("Tools".equals(role)) { group=null; }
                    else if (group==null && item.equipment && !WikiCatalogue.hasFacet(item,"outfit") && !WikiCatalogue.hasFacet(item,"cosmetic") && !WikiCatalogue.hasFacet(item,"skilling"))
                    { group="Other — equipment role needs review"; }
                }
                else { group=WikiCatalogue.category(item,preset); }
                if (group!=null) { add(groups,ItemVariantState.annotate(group,item),item); }
            }
            return groups;
        }
        if (preset==Preset.RAID_MEGA_RARES)
        {
            for (Item item : items) if (ItemTaxonomy.matchesAny(item,"twisted bow","scythe of vitur","tumeken's shadow"))
            { add(groups,ItemVariantState.needsActivityReview(item) ? ItemVariantState.reviewGroup(item) : "Raid mega-rare weapons",item); }
            return groups;
        }
        return RaidRecommendations.suggest(preset,items);
    }
    private static boolean standaloneSetWeapon(Item item,List<Item> bank)
    {
        String set=ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item)),role=ItemTaxonomy.weaponRole(ItemVariantState.familyName(item));
        if(set==null || role==null || role.equals("Tools")) { return false; }
        return bank.stream().noneMatch(other -> set.equals(ItemTaxonomy.equipmentSet(ItemVariantState.familyName(other)))
            && ItemTaxonomy.weaponRole(ItemVariantState.familyName(other))==null
            && !ItemTaxonomy.baseName(ItemVariantState.familyName(other)).equals("berserker necklace"));
    }
    static String category(Item item,boolean combat)
    {
        String n=ItemTaxonomy.baseName(ItemVariantState.familyName(item));
        String set=ItemTaxonomy.equipmentSet(n);
        if (set!=null) { return set+(ItemTaxonomy.needsRepair(item.name) ? " — repair needed" : ""); }
        if (n.contains("rock cake") || n.equals("locator orb")) { return "Health-lowering utility"; }
        if (n.startsWith("blighted ")) { return "Restricted-use supplies — blighted"; }
        if (n.equals("purple sweets")) { return "Specialist food — purple sweets"; }
        String catalogue=WikiCatalogue.category(item,Preset.ALL_CATEGORIES);
        String weapon=ItemTaxonomy.weaponRole(n);
        if (weapon!=null && !weapon.equals("Tools")) { return combat ? weapon : "Equipment"; }
        if (catalogue!=null && !catalogue.startsWith("Equipment —") && !catalogue.startsWith("Cosmetic/utility equipment")) { return catalogue; }
        String role=ItemTaxonomy.weaponRole(n);
        if (role!=null) { return combat || role.equals("Tools") ? role : "Equipment"; }
        if (catalogue!=null) { return catalogue; }
        if (item.equipment)
        {
            if (!combat) { return "Equipment"; }
            // Different styles use different units; never compare their summed bonuses.
            int styles=(item.magic>0 ? 1 : 0)+(item.ranged>0 ? 1 : 0)+(item.melee>0 ? 1 : 0);
            if (styles>1) { return "Hybrid equipment"; }
            if (item.magic>0) { return "Magic equipment"; }
            if (item.ranged>0) { return "Ranged equipment"; }
            if (item.melee>0) { return "Melee equipment"; }
            return "Defensive or utility equipment — review";
        }
        if (n.endsWith(" rune")) { return "Runes"; }
        if (item.action("Eat")) { return "Food — general, not activity advice"; }
        if (item.action("Drink"))
        {
            if (n.matches(".*(?:potion|serum|antifire|antidote|antipoison|antivenom|anti-venom).*") || n.equals("saradomin brew") || n.equals("zamorak brew") || n.equals("super restore"))
            { return "Potions — general, not activity advice"; }
            return "Drinks and brews — review";
        }
        if (n.endsWith(" ore") || n.endsWith(" logs") || n.equals("logs") || n.endsWith(" seed") || n.startsWith("grimy ") || n.endsWith(" bar") || n.equals("coal") || n.equals("pure essence") || n.equals("rune essence")) { return "Resources"; }
        return "Other — review";
    }
    static void add(Map<String,List<Item>> groups,String group,Item item)
    {
        List<Item> list=groups.computeIfAbsent(group,k -> new ArrayList<>());
        if (list.stream().noneMatch(i -> i.id==item.id)) { list.add(item); }
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageCapture;

/** Captures the current tab's full laid-out content without clicking or scrolling the game. */
final class BankCapture
{
    @Inject Client client;
    @Inject ItemManager items;
    @Inject ImageCapture capture;
    @Inject BorderRenderer borders;
    @Inject WindowMarkersConfig config;

    boolean save(List<Marker> markers)
    {
        Widget bank=client.getWidget(InterfaceID.Bankmain.UNIVERSE),grid=client.getWidget(InterfaceID.Bankmain.ITEMS);
        if(bank==null || grid==null || bank.isHidden() || grid.isHidden() || grid.getDynamicChildren()==null) { return false; }
        List<Widget> widgets=new ArrayList<>(); List<ItemAnchors.Cell> cells=new ArrayList<>();
        int width=grid.getWidth(),height=32;
        for(Widget child:grid.getDynamicChildren())
        {
            if(child==null || child.isSelfHidden() || child.getItemId()<0 || child.getItemId()==6512) { continue; }
            int x=child.getRelativeX(),y=child.getRelativeY();
            if(x<0 || y<0) { continue; }
            widgets.add(child); cells.add(new ItemAnchors.Cell(items.canonicalize(child.getItemId()),new Rectangle(x,y,36,32)));
            height=Math.max(height,y+36); width=Math.max(width,x+42);
        }
        if(widgets.isEmpty()) { return false; }
        List<Marker> visible=new ArrayList<>(); List<List<Rectangle>> regions=new ArrayList<>();
        for(Marker marker:markers)
        {
            List<Rectangle> bounds=marker.linked() ? ItemAnchors.regions(marker.linkedItemIds,cells)
                : Boolean.TRUE.equals(marker.scrollWithItems) ? java.util.Collections.singletonList(new Rectangle(marker.x,marker.y,marker.width,marker.height)) : java.util.Collections.emptyList();
            if(!bounds.isEmpty() && config.visible()) { visible.add(marker); regions.add(bounds); }
        }
        int contentHeight=height+8,totalHeight=contentHeight+60+visible.size()*22;
        if(!reasonableSize(width,totalHeight)) { return false; }
        BufferedImage image=new BufferedImage(width,totalHeight,BufferedImage.TYPE_INT_RGB);
        Graphics2D g=image.createGraphics();
        try
        {
            g.setColor(new Color(32,29,24)); g.fillRect(0,0,width,totalHeight);
            g.setFont(new Font("Arial",Font.BOLD,16));g.setColor(new Color(230,202,130));g.drawString("Bank — current tab / filter",12,24);
            Graphics2D content=(Graphics2D)g.create(0,40,width,contentHeight);
            try
            {
                for(int i=0;i<visible.size();i++)
                {
                    Marker marker=visible.get(i);
                    if(marker.backgroundArgb==null) { continue; }
                    content.setColor(new Color(marker.backgroundArgb,true));
                    for(Rectangle r:regions.get(i)) { content.fillRect(r.x,r.y,r.width,r.height); }
                }
                for(Widget child:widgets)
                {
                    BufferedImage icon=items.getImage(child.getItemId(),child.getItemQuantity(),true);
                    if(items.getItemComposition(child.getItemId()).getPlaceholderTemplateId()>0) { icon=net.runelite.client.util.ImageUtil.alphaOffset(icon,0.5f); }
                    content.drawImage(icon,child.getRelativeX(),child.getRelativeY(),null);
                }
                for(int i=0;i<visible.size();i++)
                {
                    Marker marker=visible.get(i);
                    for(Rectangle r:regions.get(i)) { borders.draw(content,r,marker.style==null ? config.style() : marker.style,marker.borderArgb==null ? config.color() : new Color(marker.borderArgb,true),marker.borderArgb!=null); }
                }
            }
            finally { content.dispose(); }
            // A separate legend retains every label without covering any item icon.
            g.setFont(new Font("Arial",Font.PLAIN,12));
            int y=contentHeight+55;
            for(Marker marker:visible)
            {
                g.setColor(marker.borderArgb==null ? config.color() : new Color(marker.borderArgb,true)); g.fillRect(12,y-10,12,12);
                g.setColor(Color.WHITE); g.drawString(MarkerPresentation.fit(marker.labelText(),g.getFontMetrics(),width-44),32,y);y+=22;
            }
        }
        finally { g.dispose(); }
        capture.saveScreenshot(image,"bank","bank-markers",true,false);
        return true;
    }
    static boolean reasonableSize(int width,int height) { return width>0 && width<=4096 && height>0 && height<=30000 && (long)width*height<=32000000; }
}

package com.windowmarkers;

import java.util.*;

/** Search the full bundled catalogue; membership remains distinct from activity readiness. */
final class BankCatalogue
{
    enum Kind { CATEGORY, PRESET, WIKI_SETUP, CUSTOM_PRESET, SAVED_GROUP }
    static final class Choice
    {
        final Kind kind;
        final String name, search;
        final Object value;
        Choice(Kind kind,String name,Object value)
        {
            this.kind=kind; this.name=name; this.value=value;
            search=SearchText.normalize(name+" "+aliases(name));
        }
        @Override public String toString() { return name+"  · "+kind.toString().toLowerCase(Locale.ROOT).replace('_',' '); }
    }
    static String aliases(String name)
    {
        return name.contains("Chambers of Xeric") ? "cox" : name.contains("Theatre of Blood") ? "tob"
            : name.contains("Tombs of Amascut") ? "toa" : name.contains("The Fractured Archive") ? "tfa" : "";
    }
    static List<Choice> choices(List<AutoCategories.Item> owned,List<Marker> markers,CustomPresets presets)
    {
        Set<String> categories=new TreeSet<>(WikiCatalogue.groups());
        categories.addAll(ItemTaxonomy.groups()); categories.addAll(RaidRecommendations.groups());
        categories.addAll(Arrays.asList("Hybrid equipment","Magic equipment","Ranged equipment","Melee equipment","Equipment",
            "Defensive or utility equipment — review","Health-lowering utility","Restricted-use supplies — blighted",
            "Specialist food — purple sweets","Runes","Food — general, not activity advice","Potions — general, not activity advice",
            "Drinks and brews — review","Resources","Other — review","Other — equipment role needs review","Raid mega-rare weapons"));
        // All preset and setup names are indexed independently of ownership. Only
        // broad groups need the current bank to discover state-specific labels.
        categories.addAll(AutoCategories.suggest(AutoCategories.Preset.ALL_CATEGORIES,owned).keySet());
        List<Choice> result=new ArrayList<>();
        for(String category:categories) result.add(new Choice(Kind.CATEGORY,category,category));
        for(AutoCategories.Preset preset:AutoCategories.Preset.values()) result.add(new Choice(Kind.PRESET,preset.toString(),preset));
        for(ActivitySetups.Setup setup:ActivitySetups.all()) result.add(new Choice(Kind.WIKI_SETUP,setup.activity+" — "+setup.label,setup));
        for(CustomPresets.Preset preset:presets.presets) result.add(new Choice(Kind.CUSTOM_PRESET,preset.name,preset));
        for(Marker marker:markers) result.add(new Choice(Kind.SAVED_GROUP,marker.labelText().isEmpty()?"Unnamed group":marker.labelText(),marker));
        return result;
    }
    static List<Choice> search(List<Choice> choices,String query,int limit)
    {
        String needle=SearchText.normalize(query);
        Map<Choice,Integer> scores=new IdentityHashMap<>();
        for(Choice choice:choices)
        {
            int score=SearchText.normalizedScore(choice.search,needle);
            if(score!=Integer.MAX_VALUE) scores.put(choice,score);
        }
        List<Choice> result=new ArrayList<>(scores.keySet());
        result.sort(Comparator.comparingInt((Choice c)->scores.get(c)).thenComparing(c->c.name).thenComparing(c->c.kind));
        return new ArrayList<>(result.subList(0,Math.min(limit,result.size())));
    }
    static Map<String,List<AutoCategories.Item>> categoryGroups(String category,List<AutoCategories.Item> items)
    {
        Map<String,List<AutoCategories.Item>> groups=new LinkedHashMap<>();
        Set<Integer> found=new HashSet<>();
        for(AutoCategories.Item item:items)
            if(!ItemVariantState.identityNeedsReview(item) && WikiCatalogue.entries(item).stream().anyMatch(e -> e.group.equals(category)) && found.add(item.id))
                groups.computeIfAbsent(ItemVariantState.annotate(category,item),k -> new ArrayList<>()).add(item);
        List<AutoCategories.Preset> matching=new ArrayList<>();
        if(category.startsWith("CoX ")) matching.add(AutoCategories.Preset.CHAMBERS_OF_XERIC);
        else if(category.startsWith("ToB ")) matching.add(AutoCategories.Preset.THEATRE_OF_BLOOD);
        else if(category.startsWith("ToA ")) matching.add(AutoCategories.Preset.TOMBS_OF_AMASCUT);
        else if(category.startsWith("TFA ")) matching.add(AutoCategories.Preset.FRACTURED_ARCHIVE);
        else matching.addAll(Arrays.asList(AutoCategories.Preset.ALL_CATEGORIES,AutoCategories.Preset.COMBAT_GROUPS,AutoCategories.Preset.RAID_MEGA_RARES));
        for(AutoCategories.Preset preset:matching)
            for(AutoCategories.Item item:AutoCategories.suggest(preset,items).getOrDefault(category,Collections.emptyList()))
                // Suggested labels already contain their state or review note.
                if(found.add(item.id)) groups.computeIfAbsent(category,k -> new ArrayList<>()).add(item);
        return groups;
    }
    static SortedSet<String> memberships(AutoCategories.Item item,List<AutoCategories.Item> owned,List<Marker> markers,CustomPresets custom)
    {
        SortedSet<String> result=new TreeSet<>();
        if(ItemVariantState.identityNeedsReview(item)) result.add("Review: "+ItemVariantState.reviewGroup(item));
        else for(WikiCatalogue.Entry entry:WikiCatalogue.entries(item)) result.add("Category: "+ItemVariantState.annotate(entry.group,item));
        // Only fellow set pieces affect this item's group. Evaluating the entire
        // bank once per preset would repeatedly classify hundreds of unrelated IDs.
        String set=ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item));
        List<AutoCategories.Item> context=new ArrayList<>();
        if(set!=null) for(AutoCategories.Item candidate:owned)
            if(set.equals(ItemTaxonomy.equipmentSet(ItemVariantState.familyName(candidate)))) context.add(candidate);
        if(context.stream().noneMatch(i -> i.id==item.id)) context.add(item);
        for(AutoCategories.Preset preset:AutoCategories.Preset.values())
            AutoCategories.suggest(preset,context).forEach((group,items) -> {
                if(items.stream().anyMatch(i -> i.id==item.id)) result.add("Preset: "+preset+" / "+group);
            });
        for(ActivitySetups.Setup setup:ActivitySetups.all()) if(setup.itemIds.contains(item.id))
            result.add("Wiki setup: "+setup.activity+" / "+setup.label+(ItemVariantState.needsActivityReview(item)?" — state needs review":""));
        for(Marker marker:markers) if(marker.linked() && Arrays.stream(marker.linkedItemIds).anyMatch(id -> id==item.id))
            result.add("Saved group: "+marker.labelText());
        for(CustomPresets.Preset preset:custom.presets) for(Marker group:preset.groups)
            if(group.linked() && Arrays.stream(group.linkedItemIds).anyMatch(id -> id==item.id)) result.add("Custom preset: "+preset.name+" / "+group.labelText());
        return result;
    }
    static String compare(String left,Set<String> a,String right,Set<String> b)
    {
        Set<String> shared=new TreeSet<>(a); shared.retainAll(b);
        Set<String> onlyA=new TreeSet<>(a); onlyA.removeAll(b);
        Set<String> onlyB=new TreeSet<>(b); onlyB.removeAll(a);
        return section("Shared",shared)+section("Only "+left,onlyA)+section("Only "+right,onlyB);
    }
    private static String section(String name,Set<String> entries)
    { return name+" ("+entries.size()+")\n"+(entries.isEmpty()?"None":String.join("\n",entries))+"\n\n"; }
}

package com.windowmarkers;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/** Incremental client-thread reads; fuzzy ranking runs off the client thread. */
final class BankItemSearch
{
    static final class Choice
    {
        final int id;
        final String name, search;
        BufferedImage image;
        Choice(int id,String name) { this.id=id; this.name=name; search=SearchText.normalize(name); }
        @Override public String toString() { return name+" (#"+id+")"; }
    }
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject ItemManager items;
    private final List<Choice> catalogue=new ArrayList<>();
    private int cursor,size;
    void search(String query,Set<Integer> allowed,BooleanSupplier wanted,Consumer<List<Choice>> done)
    {
        thread.invokeLater(() -> {
            if(!wanted.getAsBoolean()) return true;
            int count=Math.min(client.getItemCount(),100000);
            if(count!=size) { catalogue.clear(); cursor=0; size=count; }
            int end=Math.min(cursor+256,size);
            while(cursor<end)
            {
                int id=cursor++; var item=items.getItemComposition(id); String name=item.getName();
                if(name!=null && !name.isBlank() && !name.equalsIgnoreCase("null") && item.getNote()==-1 && item.getPlaceholderTemplateId()==-1)
                    catalogue.add(new Choice(id,name));
            }
            if(cursor<size) return false;
            List<Choice> snapshot=new ArrayList<>(catalogue);
            new SwingWorker<List<Choice>,Void>() {
                protected List<Choice> doInBackground() { return rank(snapshot,query,allowed); }
                protected void done() {
                    if(!wanted.getAsBoolean()) return;
                    try {
                        List<Choice> matches=get();
                        thread.invokeLater(() -> {
                            if(!wanted.getAsBoolean()) return;
                            for(Choice choice:matches) choice.image=items.getImage(choice.id);
                            SwingUtilities.invokeLater(() -> { if(wanted.getAsBoolean()) done.accept(matches); });
                        });
                    } catch(Exception ex) { done.accept(Collections.emptyList()); }
                }
            }.execute();
            return true;
        });
    }
    static List<Choice> rank(List<Choice> choices,String query,Set<Integer> allowed)
    {
        String needle=SearchText.normalize(query);
        Map<Choice,Integer> scores=new IdentityHashMap<>();
        for(Choice c:choices) if(allowed==null || allowed.contains(c.id))
        { int score=SearchText.normalizedScore(c.search,needle); if(score!=Integer.MAX_VALUE) scores.put(c,score); }
        List<Choice> result=new ArrayList<>(scores.keySet());
        result.sort(Comparator.comparingInt((Choice c)->scores.get(c)).thenComparing(c->c.name).thenComparingInt(c->c.id));
        return new ArrayList<>(result.subList(0,Math.min(80,result.size())));
    }
}

