/** Searchable real-item palette; selection is by exact ID, including same-name variants. */
final class ItemPalette extends JPanel
{
    private final JTextField query=new JTextField();
    private final JCheckBox bankOnly=new JCheckBox("Only items in this bank",true);
    private final DefaultListModel<BankItemSearch.Choice> results=new DefaultListModel<>(), selected=new DefaultListModel<>();
    private final JList<BankItemSearch.Choice> tiles=new JList<>(results), picked=new JList<>(selected);
    private final JLabel hint=new JLabel("Search by name; select pictures to add items.");
    private final javax.swing.Timer debounce;
    private volatile int revision;
    private volatile boolean closed;
    private final int limit;
    ItemPalette(BankItemSearch search,Set<Integer> bank,List<BankItemSearch.Choice> initial,int limit)
    {
        super(new BorderLayout(8,8)); this.limit=limit;
        JPanel header=new JPanel(new BorderLayout(0,4));
        query.setToolTipText("Item name, including approximate spelling. Same-name variants retain separate IDs.");
        header.add(query,BorderLayout.NORTH); header.add(bankOnly,BorderLayout.SOUTH); add(header,BorderLayout.NORTH);
        for(BankItemSearch.Choice choice:initial) selected.addElement(choice);
        tiles.setLayoutOrientation(JList.HORIZONTAL_WRAP); tiles.setVisibleRowCount(-1);
        tiles.setFixedCellWidth(125); tiles.setFixedCellHeight(68);
        tiles.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
        tiles.setCellRenderer((list,choice,index,isSelected,focus) -> {
            JLabel label=new JLabel(choice.name,choice.image==null?null:new ImageIcon(choice.image),SwingConstants.CENTER);
            label.setVerticalTextPosition(SwingConstants.BOTTOM); label.setHorizontalTextPosition(SwingConstants.CENTER);
            label.setOpaque(true); label.setBackground(isSelected?list.getSelectionBackground():list.getBackground());
            label.setForeground(isSelected?list.getSelectionForeground():list.getForeground());
            label.setBorder(BorderFactory.createEmptyBorder(4,3,4,3)); label.setToolTipText(choice.toString()); return label;
        });
        JScrollPane options=new JScrollPane(tiles); options.setPreferredSize(new Dimension(520,210));
        JPanel middle=new JPanel(new BorderLayout(0,5)); middle.add(options,BorderLayout.CENTER);
        JButton add=new JButton("Add selected items ↓"); add.addActionListener(e -> addSelected()); middle.add(add,BorderLayout.SOUTH);
        tiles.addMouseListener(new MouseAdapter() { @Override public void mouseClicked(MouseEvent e) { if(e.getClickCount()==2) addSelected(); } });
        tiles.getInputMap().put(KeyStroke.getKeyStroke("ENTER"),"add");
        tiles.getActionMap().put("add",new AbstractAction() { public void actionPerformed(ActionEvent e) { addSelected(); } });
        add(middle,BorderLayout.CENTER);
        picked.setVisibleRowCount(3); picked.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
        JPanel footer=new JPanel(new BorderLayout(0,4)); footer.add(new JScrollPane(picked),BorderLayout.CENTER);
        JButton remove=new JButton("Remove selected items"); remove.addActionListener(e -> {
            for(BankItemSearch.Choice choice:picked.getSelectedValuesList()) selected.removeElement(choice); count();
        });
        JPanel bottom=new JPanel(new GridLayout(0,1,0,4)); bottom.add(remove); bottom.add(hint); footer.add(bottom,BorderLayout.SOUTH); add(footer,BorderLayout.SOUTH);
        debounce=new javax.swing.Timer(180,e -> {
            int version=revision; String text=query.getText();
            if(!bankOnly.isSelected() && text.trim().length()<2) { hint.setText("Type at least two letters to search all items."); return; }
            hint.setText("Searching…");
            search.search(text,bankOnly.isSelected()?bank:null,()->!closed && revision==version,matches -> {
                results.clear();
                for(BankItemSearch.Choice choice:matches) {
                    results.addElement(choice);
                    if(choice.image instanceof net.runelite.client.util.AsyncBufferedImage)
                        ((net.runelite.client.util.AsyncBufferedImage)choice.image).onLoaded(() -> SwingUtilities.invokeLater(() -> { if(!closed) tiles.repaint(); }));
                }
                hint.setText(matches.size()+" matches shown · "+selected.size()+" selected"+(matches.size()==80?" · refine search":""));
            });
        }); debounce.setRepeats(false);
        query.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { refresh(); } public void removeUpdate(DocumentEvent e) { refresh(); } public void changedUpdate(DocumentEvent e) { refresh(); }
        });
        bankOnly.addActionListener(e -> refresh()); debounce.start();
    }
    private void refresh() { revision++; results.clear(); debounce.restart(); }
    private void count() { hint.setText(selected.size()+" selected"+(limit==2?" (up to two for comparison)":"")); }
    private void addSelected()
    {
        for(BankItemSearch.Choice choice:tiles.getSelectedValuesList())
        {
            boolean exists=false; for(int i=0;i<selected.size();i++) if(selected.get(i).id==choice.id) exists=true;
            if(!exists && selected.size()<limit) selected.addElement(choice);
        }
        count();
    }
    int[] ids() { return Collections.list(selected.elements()).stream().mapToInt(c -> c.id).toArray(); }
    void close() { closed=true; revision++; debounce.stop(); }
}

package com.windowmarkers;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Factual identities, not an ordering of interchangeable gear. Sources accompany bundled data. */
final class ItemTaxonomy
{
    private static final Map<String,String> WEAPONS=new HashMap<>();
    private static final Map<String,String> SETS=new HashMap<>();
    static
    {
        for (String[] row : readRows("weapon-roles.tsv",2)) { WEAPONS.put(row[0],row[1]); }
        set("Ahrim — magic set (staff required)","ahrim's hood","ahrim's robetop","ahrim's robeskirt","ahrim's staff");
        set("Dharok — melee set (greataxe required)","dharok's helm","dharok's platebody","dharok's platelegs","dharok's greataxe");
        set("Guthan — melee set (warspear required)","guthan's helm","guthan's platebody","guthan's chainskirt","guthan's warspear");
        set("Karil — ranged set (crossbow required)","karil's coif","karil's leathertop","karil's leatherskirt","karil's crossbow");
        set("Torag — melee set (hammers required)","torag's helm","torag's platebody","torag's platelegs","torag's hammers");
        set("Verac — melee set (flail required)","verac's helm","verac's brassard","verac's plateskirt","verac's flail");
        set("Blood Moon — set + dual macuahuitl","blood moon helm","blood moon chestplate","blood moon tassets","dual macuahuitl");
        set("Blue Moon — magic/melee set + spear","blue moon helm","blue moon chestplate","blue moon tassets","blue moon spear");
        set("Eclipse Moon — ranged set + atlatl","eclipse moon helm","eclipse moon chestplate","eclipse moon tassets","eclipse atlatl");
        set("Void — helm, top, robe and gloves","void melee helm","void ranger helm","void mage helm","void knight top","void knight robe","void knight gloves","elite void top","elite void robe");
        set("Inquisitor — crush armour and mace synergy","inquisitor's great helm","inquisitor's hauberk","inquisitor's plateskirt","inquisitor's mace");
        set("Crystal — bow armour synergy","crystal helm","crystal body","crystal legs","crystal bow","bow of faerdhinen");
        set("Justiciar — armour set (no required weapon)","justiciar faceguard","justiciar chestguard","justiciar legguards");
        set("Obsidian — melee armour/weapon synergy","obsidian helmet","obsidian platebody","obsidian platelegs","toktz-xil-ak","toktz-xil-ek","tzhaar-ket-om","tzhaar-ket-em","berserker necklace");
    }
    private static void set(String label,String... names) { for (String n : names) { SETS.put(n,label); } }
    static List<String[]> readRows(String file,int columns)
    {
        List<String[]> result=new ArrayList<>();
        InputStream stream=ItemTaxonomy.class.getResourceAsStream(file);
        if (stream==null) { throw new IllegalStateException("Missing taxonomy resource: "+file); }
        try (BufferedReader reader=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8)))
        {
            String line;
            while ((line=reader.readLine())!=null)
            {
                if (line.isEmpty() || line.startsWith("#")) { continue; }
                String[] row=line.split("\t",-1);
                if (row.length!=columns) { throw new IllegalStateException("Invalid taxonomy row in "+file); }
                result.add(row);
            }
        }
        catch (IOException e) { throw new IllegalStateException("Cannot read taxonomy: "+file,e); }
        return result;
    }
    static String baseName(String name)
    {
        String n=name.toLowerCase(Locale.ROOT).replace('\u2019','\'').trim();
        // Keep functional (i), (f), poisoned and (a) variants distinct.
        n=n.replaceFirst("\\s*\\([1-4]\\)$","");
        n=n.replaceFirst("\\s+(100|75|50|25|0)$","");
        n=n.replaceFirst("\\s*\\((?:uncharged|empty|inactive|broken|or|l)\\)$","");
        if (n.startsWith("holy sanguinesti staff") || n.startsWith("holy scythe of vitur") || n.startsWith("holy ghrazi rapier")) { n=n.substring(5); }
        if (n.startsWith("sanguine scythe of vitur")) { n=n.substring(9); }
        if (n.startsWith("twisted ancestral ")) { n=n.substring(8); }
        if (n.startsWith("bow of faerdhinen") || n.startsWith("blade of saeldor"))
        { n=n.replaceFirst("\\s*\\(c\\)(?:\\s*\\([a-z]+\\))?$",""); }
        return n.trim();
    }
    static boolean needsRepair(String name) { return name.endsWith(" 0") || name.contains("(broken)"); }
    static boolean needsCharge(String name) { return name.contains("(uncharged)") || name.contains("(empty)") || name.contains("(inactive)"); }
    static String equipmentSet(String n) { return SETS.get(baseName(n)); }
    static Set<String> groups()
    { Set<String> result=new TreeSet<>(SETS.values()); result.addAll(WEAPONS.values()); return result; }
    static String weaponRole(String n)
    {
        String role=WEAPONS.get(n);
        return role!=null ? role : WEAPONS.get(baseName(n));
    }
    static boolean matchesAny(String name,String... expected)
    { for (String n : expected) { if (matches(name,n)) { return true; } } return false; }
    static boolean matches(AutoCategories.Item item,String expected)
    { return matches(ItemVariantState.familyName(item),expected); }
    static boolean matchesAny(AutoCategories.Item item,String... expected)
    { return matchesAny(ItemVariantState.familyName(item),expected); }
    static boolean matches(String name,String expected)
    {
        String n=baseName(name), e=baseName(expected);
        if (n.equals(e)) { return true; }
        switch (e)
        {
            case "god capes": case "imbued god cape": return n.matches("imbued (saradomin|guthix|zamorak) cape");
            case "blessed body": return n.matches("(saradomin|guthix|zamorak|armadyl|bandos|ancient) d'hide body");
            case "blessed chaps": return n.matches("(saradomin|guthix|zamorak|armadyl|bandos|ancient) chaps");
            case "god blessing": return matchesAny(n,"holy blessing","unholy blessing","peaceful blessing","honourable blessing","war blessing","ancient blessing");
            case "ardougne cloak": return n.matches("ardougne cloak [1-4]");
            case "ancient sceptre": return n.matches("(?:blood|ice|smoke|shadow) ancient sceptre");
            case "mystic hat": case "mystic robe top": case "mystic robe bottom":
                return n.matches(java.util.regex.Pattern.quote(e)+" \\((?:light|dark|dusk)\\)");
            default: return false;
        }
    }
}

package com.windowmarkers;

import java.util.HashMap;
import java.util.Map;

/** Exact identity state is separate from category membership and activity suitability. */
final class ItemVariantState
{
    private enum State { AVAILABLE, REPAIR, CHARGE, EMPTY, REDUCED, CHECK, PREPARE, CONTENTS, RESTRICTED }
    private static final Map<Integer,ItemVariantState> STATES=new HashMap<>();
    private static final Map<Integer,String> UNVERIFIED_IDENTITIES=new HashMap<>();
    static
    {
        for (String[] row:ItemTaxonomy.readRows("identity-review-required.tsv",2))
        { UNVERIFIED_IDENTITIES.put(Integer.parseInt(row[0]),row[1]); }
        for (String[] row : ItemTaxonomy.readRows("item-variant-states.tsv",5))
        {
            int id=Integer.parseInt(row[0]);
            if (!row[3].equals("true") && !row[3].equals("false"))
            { throw new IllegalStateException("Invalid variant review policy"); }
            if (STATES.put(id,new ItemVariantState(row[1],State.valueOf(row[2]),Boolean.parseBoolean(row[3]),row[4]))!=null)
            { throw new IllegalStateException("Duplicate variant ID: "+id); }
        }
    }
    private final String family;
    private final State state;
    private final boolean activityReview;
    private final String note;

    private ItemVariantState(String family,State state,boolean activityReview,String note)
    { this.family=family; this.state=state; this.activityReview=activityReview; this.note=note; }

    static String familyName(AutoCategories.Item item)
    {
        ItemVariantState known=STATES.get(item.id);
        return known==null ? item.name : known.family;
    }

    static boolean needsActivityReview(AutoCategories.Item item)
    {
        if (identityNeedsReview(item)) { return true; }
        if (WikiCatalogue.hasFacet(item,"restricted")) { return true; }
        ItemVariantState known=STATES.get(item.id);
        return known==null ? ItemTaxonomy.needsRepair(item.name) || ItemTaxonomy.needsCharge(item.name) : known.activityReview;
    }

    static boolean needsActivityReview(AutoCategories.Item item,String role)
    {
        // The inactive Arclight keeps Darklight's special attack. This exception
        // does not grant it the charged weapon's demon-damage role or ranking.
        if (item.id==30305 && role.startsWith("Special attacks")) { return false; }
        return needsActivityReview(item);
    }

    static String reviewGroup(AutoCategories.Item item)
    {
        if (identityNeedsReview(item)) { return "Unverified item identity — review"; }
        if (WikiCatalogue.hasFacet(item,"restricted")) { return "Activity restrictions — review"; }
        ItemVariantState known=STATES.get(item.id);
        if (known!=null && known.state==State.CHECK)
        { return known.note.contains("charge") ? "Check charges — review" : "Check item use — review"; }
        if (known!=null && known.state==State.REDUCED) { return "Reduced function — review"; }
        if (known!=null && known.state==State.PREPARE) { return "Preparation needed — review"; }
        if (known!=null && known.state==State.CONTENTS) { return "Check contents — review"; }
        if (known!=null && known.state==State.EMPTY) { return "Empty — review"; }
        if (known!=null && known.state==State.RESTRICTED) { return "Activity restrictions — review"; }
        return "Needs repair/charge — review";
    }

    static String annotate(String group,AutoCategories.Item item)
    {
        if (group==null) { return null; }
        ItemVariantState known=STATES.get(item.id);
        // Keep the item's factual category, but do not mix depleted and usable states.
        if (known!=null && !known.note.isEmpty()) { return group+" ("+known.note+")"; }
        return group;
    }

    static boolean identityNeedsReview(AutoCategories.Item item)
    { return item.name.equals(UNVERIFIED_IDENTITIES.get(item.id)); }
}

