    }
    List<Marker> selected()
    { List<Marker> result=new java.util.ArrayList<>(); for(Entry entry:list.getSelectedValuesList()) result.add(entry.marker); return result; }
    private List<Marker> visible()
    { List<Marker> result=new java.util.ArrayList<>(); for(int i=0;i<rows.size();i++) result.add(rows.get(i).marker); return result; }
    private void shift(int direction)
    {
        int[] selected=list.getSelectedIndices(); if(selected.length==0 || actions==null) return;
        int index=direction<0?Math.max(0,selected[0]-1):Math.min(rows.size(),selected[selected.length-1]+2);
        actions.reorder(visible(),selected(),index);
    }
    void replace(List<Entry> entries) { replace(entries,entries); }
    void replace(List<Entry> tab,List<Entry> all)
    {
        tabEntries=tab; allEntries=all;
        String selected=(String)preset.getSelectedItem(); refreshing=true; preset.removeAllItems(); preset.addItem("All presets");
        java.util.Set<String> names=new java.util.TreeSet<>();
        for(Entry entry:all) names.add(entry.marker.preset==null?"Custom / older groups":entry.marker.preset);
        for(String name:names) preset.addItem(name);
        if(names.contains(selected)) preset.setSelectedItem(selected); refreshing=false; filter();
    }
    void catalogue(List<BankCatalogue.Choice> choices) { this.choices=choices; filter(); }
    void resetContext() { search.setText(""); preset.setSelectedIndex(0); list.clearSelection(); }
    void close() { timer.stop(); }
    void filter()
    {
        revision++; List<Marker> selected=selected(); list.setValueIsAdjusting(true); rows.clear();
        List<Entry> base=scope.getSelectedIndex()==0?tabEntries:allEntries; String needle=search.getText();
        String presetName=(String)preset.getSelectedItem();
        for(Entry entry:base)
        {
            String groupPreset=entry.marker.preset==null?"Custom / older groups":entry.marker.preset;
            if(preset.getSelectedIndex()>0 && !groupPreset.equals(presetName)) continue;
            if(SearchText.score(entry.name+" "+entry.marker.category+" "+groupPreset,needle)==Integer.MAX_VALUE) continue;
            rows.addElement(entry);
        }
        for(int i=0;i<rows.size();i++) if(selected.contains(rows.get(i).marker)) list.addSelectionInterval(i,i);
        list.setValueIsAdjusting(false);
        suggestions.clear();
        if(!needle.trim().isEmpty()) for(BankCatalogue.Choice choice:BankCatalogue.search(choices,needle,4)) suggestions.addElement(choice);
        suggestionScroll.setVisible(!suggestions.isEmpty()); revalidate(); hover.accept(null);
    }
    private final class GroupTransfer extends TransferHandler
    {
        private final java.awt.datatransfer.DataFlavor flavor=new java.awt.datatransfer.DataFlavor(
            java.awt.datatransfer.DataFlavor.javaJVMLocalObjectMimeType+";class=java.lang.Object","Legend groups");
        @Override public int getSourceActions(JComponent c) { return MOVE; }
        @Override protected java.awt.datatransfer.Transferable createTransferable(JComponent c)
        {
            Drag drag=new Drag(MarkerLegend.this,revision,visible(),selected());
            return new java.awt.datatransfer.Transferable() {
                public java.awt.datatransfer.DataFlavor[] getTransferDataFlavors() { return new java.awt.datatransfer.DataFlavor[]{flavor}; }
                public boolean isDataFlavorSupported(java.awt.datatransfer.DataFlavor f) { return flavor.equals(f); }
                public Object getTransferData(java.awt.datatransfer.DataFlavor f) throws java.awt.datatransfer.UnsupportedFlavorException {
                    if(!isDataFlavorSupported(f)) throw new java.awt.datatransfer.UnsupportedFlavorException(f); return drag;
                }
            };
        }
        @Override public boolean canImport(TransferSupport support)
        { return actions!=null && support.isDrop() && support.getComponent()==list && support.isDataFlavorSupported(flavor); }
        @Override public boolean importData(TransferSupport support)
        {
            if(!canImport(support)) return false;
            try {
                Drag drag=(Drag)support.getTransferable().getTransferData(flavor);
                if(drag.owner!=MarkerLegend.this || drag.revision!=revision) return false;
                actions.reorder(drag.visible,drag.selected,((JList.DropLocation)support.getDropLocation()).getIndex()); return true;
            } catch(java.awt.datatransfer.UnsupportedFlavorException | java.io.IOException ex) { return false; }
        }
    }
    private static final class Drag
    {
        final MarkerLegend owner; final long revision; final List<Marker> visible,selected;
        Drag(MarkerLegend owner,long revision,List<Marker> visible,List<Marker> selected)
        { this.owner=owner; this.revision=revision; this.visible=visible; this.selected=selected; }
    }
}

package com.windowmarkers;

import java.awt.*;
import java.util.List;

final class MarkerPresentation
{
    static String miniTitle(String label)
    {
        String shortTitle=displayTitle(label);
        int separator=shortTitle.indexOf(" — ");
        if(separator>=0) { shortTitle=shortTitle.substring(0,separator); }
        return shortTitle.replace(" weapons","").replace(" equipment","");
    }
    static String displayTitle(String label)
    {
        // Legacy generated descriptions can be shortened without rewriting saved custom labels.
        if(label.contains(" — ") && (label.contains("set") || label.contains("synergy") || label.startsWith("Void —")
            || label.contains("not activity advice") || label.startsWith("Restricted-use supplies"))) { return title(label); }
        return label;
    }
    static String title(String group)
    {
        for(String family:new String[]{"Ahrim","Dharok","Guthan","Karil","Torag","Verac","Blood Moon","Blue Moon","Eclipse Moon","Void","Inquisitor","Crystal","Justiciar","Obsidian"})
        { if(group.startsWith(family+" —")) { return family; } }
        if(group.startsWith("Restricted-use supplies")) { return "Blighted supplies"; }
        if(group.startsWith("Food —")) { return "Food"; }
        if(group.startsWith("Potions —")) { return "Potions"; }
        if(group.startsWith("Other —")) { return "Unclassified"; }
        return group.replaceAll("\\s*\\([^)]*\\)","").replace(" — general, not activity advice","")
            .replace(" — check current quest","").replace(" — check restrictions","");
    }
    static Color nextColor(List<Color> used)
    {
        Color best=null; double bestDistance=-1;
        for(int h=0;h<360;h+=3) for(float s:new float[]{0.5f,0.75f,1f}) for(float b:new float[]{0.65f,0.85f,1f})
        {
            Color c=Color.getHSBColor(h/360f,s,b); double nearest=Double.MAX_VALUE;
            for(Color old:used)
            {
                double r=c.getRed()-old.getRed(),g=c.getGreen()-old.getGreen(),blue=c.getBlue()-old.getBlue();
                nearest=Math.min(nearest,2*r*r+4*g*g+3*blue*blue);
            }
            if(nearest>bestDistance) { bestDistance=nearest; best=c; }
        }
        return best;
    }
    static String fit(String text,FontMetrics metrics,int width)
    {
        if(metrics.stringWidth(text)<=width) { return text; }
        while(!text.isEmpty() && metrics.stringWidth(text+"…")>width) { text=text.substring(0,text.length()-1); }
        return text.isEmpty() ? "" : text+"…";
    }
    static Rectangle place(Rectangle region,Rectangle clip,int width,int height,Marker.LabelPlacement preference,List<Rectangle> occupied)
    {
        int above=region.y-height-2,inside=region.y+2,below=region.y+region.height+2;
        int[] positions=preference==Marker.LabelPlacement.ABOVE ? new int[]{above,inside,below} : preference==Marker.LabelPlacement.BELOW ? new int[]{below,inside,above} : new int[]{inside,above,below};
        int x=Math.max(clip.x,Math.min(region.x+3,clip.x+clip.width-width));
        for(int y:positions)
        {
            Rectangle candidate=new Rectangle(x,y,width,height);
            if(!clip.contains(candidate)) { continue; }
            if(occupied.stream().noneMatch(candidate::intersects)) { occupied.add(candidate); return candidate; }
        }
        return null;
    }
}

package com.windowmarkers;

import java.util.*;
import javax.inject.Inject;
import javax.swing.SwingWorker;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsService;

/** Adds only owned search UI and optional matches; native/tag restrictions remain authoritative. */
final class NativeBankSearch
{
    @Inject Client client;
    @Inject ClientThread clientThread;
    @Inject ConfigManager configs;
    @Inject WindowMarkersConfig config;
    @Inject ItemManager itemManager;
    @Inject BankSearch bankSearch;
    @Inject BankTagsService bankTags;
    private Widget parent,checkbox;
    private BankSearchIndex index;
    private String query;
    private Set<Integer> matches=Collections.emptySet();
    private Marker highlight;
    private long revision;
    private boolean running;
    private volatile long context;

    void start() { running=true; }
    void stop() { boolean restore=searching(); running=false; reset(); clearWidget(); if(restore) bankSearch.layoutBank(); }
    void reset() { context++; revision++; query=null; index=null; matches=Collections.emptySet(); highlight=null; if(checkbox!=null) checkbox.setHidden(true); }
    void index(BankSearchIndex next)
    { final long owner=context; clientThread.invokeLater(() -> { if(running && owner==context) { index=next; query=null; revision++; update(); } }); }
    boolean searching()
    {
        Widget bank=client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        return running && client.getGameState()==GameState.LOGGED_IN && bank!=null && !bank.isHidden()
            && client.getVarcIntValue(VarClientID.MESLAYERMODE)==InputType.SEARCH.getType();
    }
    void update()
    {
        if(!searching()) {
            if(query!=null) { revision++; query=null; matches=Collections.emptySet(); highlight=null; }
            if(checkbox!=null) checkbox.setHidden(true); return;
        }
        updateCheckbox();
        String next=client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        if(!config.improvedBankSearch()) next="";
        if(Objects.equals(query,next)) return;
        query=next; matches=Collections.emptySet(); highlight=null; final long token=++revision;
        final BankSearchIndex snapshot=index; final String text=next;
        if(snapshot==null || !BankSearchIndex.plainQuery(text)) return;
        new SwingWorker<Set<Integer>,Void>() {
            protected Set<Integer> doInBackground() { return snapshot.find(text); }
            protected void done() { try {
                final Set<Integer> found=get();
                clientThread.invokeLater(() -> {
                    if(!running || token!=revision || !searching() || !config.improvedBankSearch()
                        || !Objects.equals(text,client.getVarcStrValue(VarClientID.MESLAYERINPUT))) return;
                    matches=found;
                    // A tab's own membership must not be expanded by category search.
                    if(bankTags.getActiveBankTag()!=null) matches.removeIf(id -> !bankTags.getActiveBankTag().contains(id));
                    if(!matches.isEmpty()) {
                        highlight=new Marker(0,0,48,36); highlight.scrollWithItems=true;
                        highlight.linkedItemIds=matches.stream().mapToInt(Integer::intValue).toArray();
                    }
                    bankSearch.layoutBank();
                });
            } catch(Exception ex) { /* Native search remains available if the optional index fails. */ } }
        }.execute();
    }
    void filter(ScriptCallbackEvent event)
    {
        if(!"bankSearchFilter".equals(event.getEventName()) || !searching() || !config.improvedBankSearch()) return;
        int size=client.getIntStackSize(),strings=client.getObjectStackSize();
        if(size<2 || strings<1) return;
        Object raw=client.getObjectStack()[strings-1];
        if(!(raw instanceof String) || !Objects.equals(query,raw) || !BankSearchIndex.plainQuery(query)) return;
        int id=client.getIntStack()[size-1]; if(id<0) return;
        if(bankTags.getActiveBankTag()!=null && !bankTags.getActiveBankTag().contains(id)) return;
        if(matches.contains(itemManager.canonicalize(id))) client.getIntStack()[size-2]=1;
    }
    Marker highlight() { return highlight; }
    private void updateCheckbox()
    {
        Widget layer=client.getWidget(InterfaceID.Chatbox.MES_LAYER);
        if(layer==null || layer.isHidden() || layer.getWidth()<260 || layer.getHeight()<85) {
            if(checkbox!=null) checkbox.setHidden(true); return;
        }
        if(parent!=layer || checkbox==null || layer.getChildren()==null || !Arrays.asList(layer.getChildren()).contains(checkbox)) {
            clearWidget(); parent=layer; checkbox=layer.createChild(-1,WidgetType.TEXT);
            checkbox.setFontId(494); checkbox.setOriginalWidth(254); checkbox.setOriginalHeight(18);
            checkbox.setTextColor(0xFFFFFF); checkbox.setTextShadowed(true);
            checkbox.setAction(0,"Toggle Improved Banking search");
            checkbox.setOnOpListener((JavaScriptCallback)e -> {
                if(!searching()) return;
                configs.setConfiguration("windowmarkers","improvedBankSearch",!config.improvedBankSearch());
                query=null; revision++; matches=Collections.emptySet(); highlight=null; update(); bankSearch.layoutBank();
            });
            checkbox.setHasListener(true);
        }
        checkbox.setOriginalX((layer.getWidth()-254)/2); checkbox.setOriginalY(layer.getHeight()-22);
        checkbox.setText((config.improvedBankSearch()?"[x] ":"[ ] ")+"Enable Improved Banking search");
        checkbox.setHidden(false); checkbox.revalidate();
    }
    private void clearWidget()
    {
        if(checkbox!=null) { checkbox.setHidden(true); checkbox.clearActions(); checkbox.setOnOpListener((Object[])null); checkbox.setHasListener(false); }
        checkbox=null; parent=null;
    }
}

package com.windowmarkers;

import java.util.*;

/** Per-role substitutions only; never removes an item from its other raid uses. */
final class RaidGearFilter
{
    private static final List<String[]> RANKS=ItemTaxonomy.readRows("raid-ranks.tsv",5);
    private static final List<String[]> REQUIREMENTS=ItemTaxonomy.readRows("raid-wear-requirements.tsv",8);
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,Map<Integer,String> exclusions)
    { filter(preset,groups,levels,false,exclusions); }
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,boolean ancientRingsUnlocked,Map<Integer,String> exclusions)
    { filter(preset,groups,levels,ancientRingsUnlocked,false,exclusions); }
    static void filter(AutoCategories.Preset preset,Map<String,List<AutoCategories.Item>> groups,int[] levels,boolean ancientRingsUnlocked,boolean allSkillsMaxed,Map<Integer,String> exclusions)
    {
        if(preset!=AutoCategories.Preset.CHAMBERS_OF_XERIC && preset!=AutoCategories.Preset.THEATRE_OF_BLOOD && preset!=AutoCategories.Preset.TOMBS_OF_AMASCUT) { return; }
        String raid=RaidRecommendations.raid(preset);
        for(Map.Entry<String,List<AutoCategories.Item>> group:groups.entrySet())
        {
            String style=group.getKey().contains("Magic") ? "Magic" : group.getKey().contains("Ranged") ? "Ranged" : group.getKey().endsWith("Melee") ? "Melee" : "";
            if(style.isEmpty()) { continue; }
            List<AutoCategories.Item> candidates=new ArrayList<>(group.getValue());
            group.getValue().removeIf(item -> {
                if(protectedUse(item)) { return false; }
                for(String[] lower:RANKS)
                {
                    if(!lower[0].equals(raid) || !lower[1].equals(style) || !CombatEquivalence.matches(item,lower[4])) { continue; }
                    for(String[] higher:RANKS)
                    {
                        if(!higher[0].equals(raid) || !higher[1].equals(style) || !higher[2].equals(lower[2]) || Integer.parseInt(higher[3])>=Integer.parseInt(lower[3])) { continue; }
                        for(AutoCategories.Item upgrade:candidates)
                        {
                            if(upgrade.id==item.id || protectedUse(upgrade) || !CombatEquivalence.matches(upgrade,higher[4]) || !sameRole(lower[2],item,upgrade) || !canWear(upgrade,levels,ancientRingsUnlocked,allSkillsMaxed)) { continue; }
                            String reason=group.getKey()+": "+item.name+" → "+upgrade.name+" (Wiki "+lower[2].toLowerCase(Locale.ROOT)+" ranking)";
                            exclusions.merge(item.id,reason,(a,b) -> a+"; "+b); return true;
                        }
                    }
                }
                return false;
            });
        }
        groups.values().removeIf(List::isEmpty);
    }
    private static boolean canWear(AutoCategories.Item item,int[] levels,boolean ancientRingsUnlocked,boolean allSkillsMaxed)
    {
        if(CombatEquivalence.requiresMaxedSkills(item) && !allSkillsMaxed) { return false; }
        if(ItemTaxonomy.matchesAny(item,"ultor ring","magus ring","venator ring","bellator ring")) { return ancientRingsUnlocked; }
        for(String[] row:REQUIREMENTS)
        {
            if(!CombatEquivalence.matches(item,row[0])) { continue; }
            for(int i=0;i<7;i++) { if((i<levels.length ? levels[i] : 1)<Integer.parseInt(row[i+1])) { return false; } }
            return true;
        }
        return false;
    }
    private static boolean sameRole(String slot,AutoCategories.Item lower,AutoCategories.Item higher)
    {
        String n=ItemTaxonomy.baseName(CombatEquivalence.familyName(lower));
        if(slot.contains("weapon"))
        {
            // Explicit substitutions, not a blanket comparison of a row containing multiple loadout roles.
            if(n.equals("abyssal whip")) { return CombatEquivalence.matchesAny(higher,"abyssal tentacle","blade of saeldor"); }
            if(n.equals("trident of the seas")) { return CombatEquivalence.matchesAny(higher,"trident of the swamp","sanguinesti staff"); }
            if(n.equals("warped sceptre")) { return CombatEquivalence.matchesAny(higher,"trident of the seas","trident of the swamp","sanguinesti staff"); }
            if(n.equals("rune crossbow")) { return CombatEquivalence.matchesAny(higher,"dragon crossbow","armadyl crossbow","zaryte crossbow","dragon hunter crossbow"); }
            return false;
        }
        if(slot.equals("Ring"))
        {
            return (n.equals("berserker ring (i)") && CombatEquivalence.matches(higher,"ultor ring"))
                || (n.equals("seers ring (i)") && CombatEquivalence.matches(higher,"magus ring"));
        }
        if(slot.equals("Shield"))
        {
            return (n.equals("dragon defender") && CombatEquivalence.matches(higher,"avernic defender"))
                || (n.equals("elidinis' ward") && CombatEquivalence.matches(higher,"elidinis' ward (f)"));
        }
        return true;
    }
    private static boolean protectedUse(AutoCategories.Item item)
    {
        String n=ItemTaxonomy.baseName(CombatEquivalence.familyName(item));
        return ItemVariantState.needsActivityReview(item)
            || ItemTaxonomy.equipmentSet(n)!=null || n.startsWith("virtus ") || n.startsWith("bloodbark ")
            || n.startsWith("oathplate ") || n.equals("serpentine helm") || n.contains("blood fury")
            || n.startsWith("mixed hide ");
    }
}

package com.windowmarkers;

import java.util.*;

/** Explicit per-activity membership from the cited Wiki tables, plus reviewed supply lists. */
final class RaidRecommendations
{
    private static final List<String[]> EQUIPMENT=new ArrayList<>();
    static
    {
        EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-equipment.tsv",3));
        EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-context-equipment.tsv",3));
    }

    static Map<String,List<AutoCategories.Item>> suggest(AutoCategories.Preset preset,List<AutoCategories.Item> items)
    {
        String raid=raid(preset), prefix=raid.equals("cox") ? "CoX" : raid.equals("tob") ? "ToB" : raid.equals("tfa") ? "TFA" : "ToA";
        Map<String,List<AutoCategories.Item>> groups=new LinkedHashMap<>();
        for (String[] row : EQUIPMENT)
        {
            if (!row[0].equals(raid)) { continue; }
            for (AutoCategories.Item item : items)
            {
                if (!CombatEquivalence.matches(item,row[2])) { continue; }
                // Learner alternatives repeated in a main-role table use that role's group and filtering.
                if(row[1].startsWith("Learner") && EQUIPMENT.stream().anyMatch(other -> other[0].equals(raid)
                    && !other[1].startsWith("Learner") && CombatEquivalence.matches(item,other[2]))) { continue; }
                String group=row[1];
                if (ItemVariantState.needsActivityReview(item,group))
                { group=ItemVariantState.reviewGroup(item); }
                else if (isVoid(ItemVariantState.familyName(item)))
                { group=completeVoid(items) ? "Elite Void switches — choose helm for role" : "Incomplete Void set — review"; }
                else if (isCrystal(ItemVariantState.familyName(item)))
                { group=completeCrystal(items) ? "Crystal bow setup" : "Incomplete crystal setup — review"; }
                else if (raid.equals("tob") && group.equals("Magic")) { group="Magic switches — freezer role"; }
                else if (raid.equals("tob") && group.equals("Ranged")) { group="Ranged switches — ranger/Tbow use"; }
                if (raid.equals("tfa") && !group.contains("review")) { group+=" — provisional review"; }
                // Keep combat role keys stable for the same-role upgrade filter.
                if (group.startsWith("Guardians tools") || group.startsWith("Special attacks"))
                { group=ItemVariantState.annotate(group,item); }
                AutoCategories.add(groups,prefix+" "+group,item);
            }
        }
        for (AutoCategories.Item item : items)
        {
            String supply=supplyGroup(raid,ItemVariantState.familyName(item));
            if (supply!=null)
            {
                if (ItemVariantState.needsActivityReview(item)) { supply=ItemVariantState.reviewGroup(item); }
                if (raid.equals("tfa")) { supply+=" — provisional review"; }
                AutoCategories.add(groups,prefix+" "+supply,item);
            }
        }
        return groups;
    }

    static String raid(AutoCategories.Preset preset)
    { return preset==AutoCategories.Preset.CHAMBERS_OF_XERIC ? "cox" : preset==AutoCategories.Preset.THEATRE_OF_BLOOD ? "tob" : preset==AutoCategories.Preset.FRACTURED_ARCHIVE ? "tfa" : "toa"; }

    /** Discoverable names even when none of the relevant items are currently owned. */
    static Set<String> groups()
    {
        Set<String> result=new TreeSet<>();
        for(String raid:Arrays.asList("cox","tob","toa","tfa")) {
            String prefix=raid.equals("cox")?"CoX":raid.equals("tob")?"ToB":raid.equals("toa")?"ToA":"TFA";
            Set<String> roles=new TreeSet<>();
            for(String[] row:EQUIPMENT) if(row[0].equals(raid)) {
                String role=row[1];
                if(raid.equals("tob") && role.equals("Magic")) role="Magic switches — freezer role";
                if(raid.equals("tob") && role.equals("Ranged")) role="Ranged switches — ranger/Tbow use";
                roles.add(role);
            }
            roles.addAll(Arrays.asList("Elite Void switches — choose helm for role","Incomplete Void set — review","Crystal bow setup","Incomplete crystal setup — review"));
            roles.addAll(Arrays.asList("Needs repair/charge — review","Check charges — review","Unverified item identity — review",
                "Activity restrictions — review","Check item use — review","Reduced function — review","Preparation needed — review","Check contents — review","Empty — review"));
            for(String name:Arrays.asList("saradomin brew","super restore","prayer potion","stamina potion","sanfew serum",
                "super combat potion","ranging potion","anglerfish","cooked karambwan","saturated heart","salve amulet (e)","salve amulet(ei)",
                "water rune","blood rune","air rune","antidote++","keris partisan of the sun","rune pouch")) {
                String group=supplyGroup(raid,name); if(group!=null) roles.add(group);
            }
            for(String role:roles) result.add(prefix+" "+role+(raid.equals("tfa") && !role.contains("review")?" — provisional review":""));
        }
        return result;
    }

    static String source(AutoCategories.Preset preset)
    {
        switch (preset)
        {
            case CHAMBERS_OF_XERIC: return "https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies";
            case THEATRE_OF_BLOOD: return "https://oldschool.runescape.wiki/w/Theatre_of_Blood/Strategies";
            case TOMBS_OF_AMASCUT: return "https://oldschool.runescape.wiki/w/Tombs_of_Amascut/Strategies";
            case FRACTURED_ARCHIVE: return "https://oldschool.runescape.wiki/w/The_Fractured_Archive/Strategies";
            default: return "https://oldschool.runescape.wiki/w/Weapons/Types";
        }
    }

    static boolean defaultSelected(String group)
    { return !group.startsWith("Other") && !group.contains("review") && !group.contains("Incomplete") && !group.contains("Needs repair"); }

    private static boolean owns(List<AutoCategories.Item> items,String... names)
    { return items.stream().anyMatch(i -> !ItemVariantState.needsActivityReview(i) && ItemTaxonomy.matchesAny(i,names)); }

    private static boolean completeVoid(List<AutoCategories.Item> items)
    {
        return owns(items,"elite void top") && owns(items,"elite void robe") && owns(items,"void knight gloves")
            && owns(items,"void melee helm","void ranger helm","void mage helm");
    }

    private static boolean completeCrystal(List<AutoCategories.Item> items)
    { return owns(items,"crystal helm") && owns(items,"crystal body") && owns(items,"crystal legs") && owns(items,"bow of faerdhinen"); }

    private static boolean isVoid(String name)
    { String set=ItemTaxonomy.equipmentSet(name); return set!=null && set.startsWith("Void —"); }

    private static boolean isCrystal(String name)
    { String set=ItemTaxonomy.equipmentSet(name); return set!=null && set.startsWith("Crystal —"); }

    static String supplyGroup(String raid,String name)
    {
        String n=ItemTaxonomy.baseName(name);
        // Intentionally positive lists: no Drink/Eat inference, substring matches, or blanket potion/rune groups.
        if (raid.equals("tob"))
        {
            if (oneOf(n,"saradomin brew","super restore","prayer potion","stamina potion")) { return "Restoration supplies"; }
            if (oneOf(n,"super combat potion","divine super combat potion","ranging potion")) { return "Combat boosts — role/prepot"; }
            if (oneOf(n,"anglerfish")) { return "Food — overheal/Maiden"; }
            if (oneOf(n,"cooked karambwan")) { return "Food — combo eating"; }
            if (oneOf(n,"saturated heart","imbued heart")) { return "Magic boost — freezer role"; }
            if (oneOf(n,"salve amulet (e)","salve amulet(ei)","salve amulet (ei)")) { return "Bloat — undead melee"; }
            if (oneOf(n,"water rune","death rune","blood rune")) { return "Ice Barrage runes — Ancients/freezer"; }
        }
        else if (raid.equals("cox"))
        {
            if (oneOf(n,"saradomin brew","super restore","prayer potion")) { return "Restoration supplies"; }
            if (oneOf(n,"stamina potion")) { return "Stamina — solo Olm/running"; }
            if (oneOf(n,"sanfew serum")) { return "Poison protection — shamans"; }
            if (oneOf(n,"super combat potion","ranging potion")) { return "Combat boosts — layout/prepot"; }
            if (oneOf(n,"anglerfish")) { return "Food — pre-raid overheal"; }
            if (oneOf(n,"salve amulet(ei)","salve amulet (ei)")) { return "Mystics — no Shadow setup"; }
        }
        else if (raid.equals("toa"))
        {
            if (oneOf(n,"saradomin brew")) { return "Brews — excludes Dehydration"; }
            if (oneOf(n,"super restore","prayer potion","sanfew serum")) { return "Prayer/restoration supplies"; }
            if (oneOf(n,"super combat potion","divine super combat potion","ranging potion","divine ranging potion")) { return "Combat boosts — path/prepot"; }
            if (oneOf(n,"antidote++")) { return "Poison protection — path dependent"; }
            if (oneOf(n,"anglerfish")) { return "Food — pre-raid (On a Diet restricts eating)"; }
            if (oneOf(n,"saturated heart","imbued heart")) { return "Magic boost — pre-raid"; }
            if (oneOf(n,"keris partisan of the sun")) { return "Healing utility — needs special energy"; }
        }
        else if (raid.equals("tfa"))
        {
            if (oneOf(n,"saradomin brew","super restore","sanfew serum")) { return "Restoration supplies"; }
            if (oneOf(n,"super combat potion","ranging potion")) { return "Combat boosts"; }
            if (oneOf(n,"blood rune","soul rune","death rune","water rune","fire rune","aether rune"))
            { return "Rune pouch alternatives — match spells and role"; }
        }
        if (oneOf(n,"rune pouch","divine rune pouch","book of the dead")) { return "Spell supplies — choose spellbook"; }
        if (raid.equals("tfa")) { return null; }
        if (oneOf(n,"air rune","cosmic rune","blood rune")) { return "Thrall runes — Arceuus only"; }
        return null;
    }
    private static boolean oneOf(String name,String... names) { return Arrays.asList(names).contains(name); }
}

package com.windowmarkers;

import java.text.Normalizer;
import java.util.Locale;

/** Shared, bounded typo matching for names, categories and presets. */
final class SearchText
{
    static String normalize(String text)
    {
        return Normalizer.normalize(text==null ? "" : text,Normalizer.Form.NFKD)
            .replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replace("'","").replace("’","")
            .replaceAll("[^a-z0-9]+"," ").trim();
    }
    static int score(String text,String query)
    { return normalizedScore(normalize(text),normalize(query)); }
    static int normalizedScore(String text,String query)
    {
        if(query.isEmpty() || text.equals(query)) return 0;
        if(text.startsWith(query)) return 1;
        if(text.contains(query)) return 2;
        int score=3;
        String[] words=text.split(" ");
        for(String needle:query.split(" "))
        {
            if(text.contains(needle)) continue;
            int allowed=needle.length()<4 ? 0 : needle.length()<8 ? 1 : 2;
            boolean match=false;
            for(String word:words) if(Math.abs(word.length()-needle.length())<=allowed && distance(word,needle)<=allowed)
            { match=true; break; }
            if(!match) return Integer.MAX_VALUE;
            score+=2;
        }
        return score;
    }
    private static int distance(String a,String b)
    {
        int[][] d=new int[a.length()+1][b.length()+1];
        for(int i=0;i<=a.length();i++) d[i][0]=i;
        for(int j=0;j<=b.length();j++) d[0][j]=j;
        for(int i=1;i<=a.length();i++) for(int j=1;j<=b.length();j++)
        {
            d[i][j]=Math.min(d[i-1][j]+1,Math.min(d[i][j-1]+1,d[i-1][j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1)));
            if(i>1 && j>1 && a.charAt(i-1)==b.charAt(j-2) && a.charAt(i-2)==b.charAt(j-1))
                d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1);
        }
        return d[a.length()][b.length()];
    }
}

package com.windowmarkers;

import java.util.*;

/** Bundled, audited Wiki item identities and useful roles. Does not imply activity eligibility. */
final class WikiCatalogue
{
    static final class Entry
    {
        final String facet, group;
        Entry(String facet,String group) { this.facet=facet; this.group=group; }
    }
    private static final Map<String,List<Entry>> INDEX=new HashMap<>();
    private static final Map<String,List<Entry>> CATEGORY_SUPPLEMENT=new HashMap<>();
    private static final Map<String,List<Entry>> ROLE_EXCLUSIONS=new HashMap<>();
    private static final Set<Integer> AMBIGUOUS_NAMES=new HashSet<>();
    private static final Set<Integer> EXCLUDED_IDENTITIES=new HashSet<>();
    static
    {
        for (String[] row : ItemTaxonomy.readRows("item-catalogue.tsv",3))
        { INDEX.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2])); }
        for (String[] row:ItemTaxonomy.readRows("ambiguous-item-names.tsv",1))
        { AMBIGUOUS_NAMES.add(Integer.parseInt(row[0])); }
        for (String[] row:ItemTaxonomy.readRows("catalogue-identity-exclusions.tsv",1))
        { EXCLUDED_IDENTITIES.add(Integer.parseInt(row[0])); }
        // Exact-ID Wiki category evidence supplements organizational roles only.
        // Raid recommendations and ranked alternatives use their own reviewed resources.
        for (String resource : new String[]{"wiki-category-supplement.tsv","combat-equivalence-categories.tsv","wiki-recipe-roles.tsv"})
        for (String[] row : ItemTaxonomy.readRows(resource,3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Wiki category requires an exact item ID"); }
            List<Entry> entries=CATEGORY_SUPPLEMENT.computeIfAbsent(row[0],k -> new ArrayList<>());
            if (entries.stream().noneMatch(e -> e.facet.equals(row[1]) && e.group.equals(row[2])))
            { entries.add(new Entry(row[1],row[2])); }
        }
        for (String[] row : ItemTaxonomy.readRows("catalogue-role-exclusions.tsv",3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Role correction requires an exact item ID"); }
            ROLE_EXCLUSIONS.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2]));
        }
    }
    static List<Entry> entries(AutoCategories.Item item)
    {
        if (EXCLUDED_IDENTITIES.contains(item.id)) { return Collections.emptyList(); }
        List<Entry> result=INDEX.get("I:"+item.id);
        boolean nameSafe=!AMBIGUOUS_NAMES.contains(item.id);
        if (result==null && nameSafe) { result=INDEX.get("N:"+item.name); }
        if (result==null && nameSafe) { result=INDEX.get("N:"+ItemTaxonomy.baseName(item.name)); }
        if (result==null && nameSafe && item.name.matches(".*\\s*\\([1-8]\\)$"))
        {
            List<Entry> charged=INDEX.get("N:"+item.name.replaceFirst("\\s*\\([1-8]\\)$",""));
            if (charged!=null && charged.stream().anyMatch(e -> e.facet.equals("travel"))) { result=charged; }
        }
        List<Entry> supplement=CATEGORY_SUPPLEMENT.get("I:"+item.id);
        List<Entry> exclusions=ROLE_EXCLUSIONS.get("I:"+item.id);
        if (supplement==null && exclusions==null) { return result==null ? Collections.emptyList() : result; }
        // Preserve reviewed name aliases when adding an exact-ID category record.
        List<Entry> combined=result==null ? new ArrayList<>() : new ArrayList<>(result);
        if (supplement!=null) for (Entry entry:supplement)
        {
            if (combined.stream().noneMatch(e -> e.facet.equals(entry.facet) && e.group.equals(entry.group)))
            { combined.add(entry); }
        }
        // Correct only the reviewed identity and role, including a name fallback
        // from a different item with the same display name. Shared indexes stay intact.
        if (exclusions!=null)
        { combined.removeIf(e -> exclusions.stream().anyMatch(x -> x.facet.equals(e.facet) && x.group.equals(e.group))); }
        return combined;
    }
    static boolean hasFacet(AutoCategories.Item item,String facet)
    { return entries(item).stream().anyMatch(e -> e.facet.equals(facet)); }

    static Set<String> groups()
    {
        Set<String> groups=new TreeSet<>();
        for(Map<String,List<Entry>> index:Arrays.asList(INDEX,CATEGORY_SUPPLEMENT))
            for(List<Entry> entries:index.values()) for(Entry entry:entries) groups.add(entry.group);
        return groups;
    }

    static String category(AutoCategories.Item item,AutoCategories.Preset preset)
    {
        if (preset==AutoCategories.Preset.FOOD_AND_POTIONS && !hasFacet(item,"supply") && !hasFacet(item,"restricted") && !item.action("Eat") && !item.action("Drink")) { return null; }
        Entry best=null;
        for (Entry entry : entries(item))
        {
            if (!accepts(preset,entry)) { continue; }
            if (best==null || priority(entry)<priority(best) || (priority(entry)==priority(best) && entry.group.compareTo(best.group)<0)) { best=entry; }
        }
        return best==null ? null : best.group;
    }
    private static int priority(Entry e)
    {
        switch (e.facet)
        {
            case "outfit": return 0;
            case "restricted": return 1;
            case "boost": return 2;
            case "skilling": return e.group.contains("materials") || e.group.contains("ingredients") || e.group.contains("products")
                || e.group.endsWith("recipe inputs") || e.group.endsWith("guild access") || e.group.endsWith("pouch protection") || e.group.endsWith("warm clothing") ? 9 : 3;
            case "travel": return 4;
            case "combat": return e.group.startsWith("Prayer") ? 7 : 5;
            case "supply": return 6;
            case "utility": return 8;
            case "quest": return 10;
            case "clue": return 11;
            default: return 12;
        }
    }
    private static boolean accepts(AutoCategories.Preset p,Entry e)
    {
        switch (p)
        {
            case ALL_CATEGORIES: case BROAD_TYPES: return true;
            case SKILLING: return e.facet.equals("outfit") || e.facet.equals("skilling") || (e.facet.equals("boost") && !e.group.startsWith("Combat"));
            case SKILLING_OUTFITS: return e.facet.equals("outfit");
            case COMBAT_GROUPS: return e.facet.equals("combat") || (e.facet.equals("boost") && e.group.startsWith("Combat"));
            case FOOD_AND_POTIONS: return e.facet.equals("supply") || e.facet.equals("boost") || e.facet.equals("restricted");
            case TRAVEL_AND_UTILITY: return e.facet.equals("travel") || e.facet.equals("utility");
            case QUESTS_AND_CLUES: return e.facet.equals("quest") || e.facet.equals("clue");
            case COSMETICS: return e.facet.equals("cosmetic");
            default: return false;
        }
    }
    static String source(AutoCategories.Preset preset)
    {
        switch (preset)
        {
            case SKILLING: case SKILLING_OUTFITS: return "https://oldschool.runescape.wiki/w/Skilling_equipment";
            case FOOD_AND_POTIONS: return "https://oldschool.runescape.wiki/w/Potions";
            case TRAVEL_AND_UTILITY: return "https://oldschool.runescape.wiki/w/Container_items";
            case QUESTS_AND_CLUES: return "https://oldschool.runescape.wiki/w/Quest_items";
            case COSMETICS: return "https://oldschool.runescape.wiki/w/Clothes";
            case ALL_CATEGORIES: case BROAD_TYPES: case COMBAT_GROUPS: return "https://oldschool.runescape.wiki/w/Equipment";
            default: return RaidRecommendations.source(preset);
        }
    }
}

