    {
        if (!currentLayout()) { load(); return; }
        String snapshot=gson.toJson(markers);
        if (record) { history.record(snapshot); }
        configs.setConfiguration("windowmarkers", accountKey, layoutKey, snapshot);
        refreshRows();
    }

