        Map<String,List<AutoCategories.Item>> ranged=filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC,new int[]{99,99,99,99,99,99},item(-1,"Masori body (f)"),item(-2,"Armadyl chestplate"));
        assertFalse(has(ranged,-2));
